word('s-inscrire','fr:s-inscrire:enrol-on-course','s’inscrire','записываться на обучение','сэ(н)скри́р',2,ex('Je voudrais m’inscrire à cette formation.','Мне бы хотелось записаться на эту программу обучения.','жё вудрэ мэ(н)скрир а сэт формасьо́(н)'),['Записываться на обучение','Изучать предмет','Платить'],0,'Вы хотите записаться на выбранную программу.',[('Je voudrais payer par carte.','жё вудрэ пэйе пар ка́рт'),('Je voudrais m’inscrire à cette formation.','жё вудрэ мэ(н)скрир а сэт формасьо́(н)'),('Je voudrais préciser le tarif.','жё вудрэ прэсизэ лё тари́ф')],1)
word('obligatoire','fr:obligatoire:required-in-course','obligatoire','обязательный в условиях учебной ситуации','облигатуа́р',3,ex('Le livre est obligatoire.','Книга обязательна по условиям этой учебной ситуации.','лё ливр э тоблигатуа́р'),['Необязательный','Обязательный','Бесплатный'],1,'Сообщите, что книга обязательна, а не просто назовите своё желание.',[('Je voudrais un livre.','жё вудрэ э(н) ли́вр'),('J’ai un livre.','жэ э(н) ли́вр'),('Le livre est obligatoire.','лё ливр э тоблигатуа́р')],2)
word('paiement','fr:paiement:payment','un paiement','оплата, платёж','э(н) пэма́(н)',4,ex('Paiement : par carte ou en espèces.','Оплата: картой или наличными.','пэма(н): пар карт у а(н) нэспэ́с'),['Опыт обучения','Оплата','Расписание'],1,'Назовите оплату как действие или платёж.',[('Un paiement.','э(н) пэма́(н)'),('Un horaire.','э(н) норэ́р'),('Une formation.','юн формасьо́(н)')],0)
word('comment-payer','fr:comment-payer:ask-payment-method','comment payer ?','как оплатить? вопрос о способе оплаты','кома(н) пэйе́',4,ex('Comment payer ?','Как оплатить?','кома(н) пэйе́'),['Каков опыт обучения?','Когда занятие?','Как оплатить?'],2,'Вы хотите узнать способ оплаты, а не только цену.',[('Pourriez-vous préciser le tarif ?','пурье ву прэсизэ лё тари́ф'),('Comment payer ?','кома(н) пэйе́'),('Pourriez-vous préciser l’horaire ?','пурье ву прэсизэ лорэ́р')],1)
for w,g,b in [('deja-experience','Сообщён прежний опыт изучения французского.','Отрицание опыта и желание учиться не утверждают, что такой опыт уже был.'),('jamais-experience','Сообщено, что указанного опыта раньше не было.','Уже учил — другое сообщение; желание учиться само по себе не отрицает прежнего опыта.'),('formation','Названа программа обучения.','Запись — действие оформления участия, отдельное занятие — часть программы.'),('inscription','Названа запись на обучение.','Программа и расписание — другие сведения, не сама запись.'),('s-inscrire','Выбрано желание записаться на программу.','Оплата и уточнение тарифа сами по себе не выражают действие записи.'),('obligatoire','Книга названа обязательной по условиям ситуации.','Желание иметь книгу и наличие книги не сообщают о требовании.'),('paiement','Названа оплата.','Расписание и программа обучения не являются названием платежа.'),('comment-payer','Вопрос прямо спрашивает способ оплаты.','Цена и расписание — другие детали; они не заменяют вопрос о способе оплаты.')]:W[w]['review_items'][1]['feedback']=fb(g,b)
for w in ['deja-experience','jamais-experience']:W[w]['review_items'][0]['prompt']=fr(W[w]['example']['fr'],W[w]['example']['transcription_ru'])

def reading(s,gs,vs,av,q,f,p,cs,a,g,b):return choose(s,'reading',gs,vs,av,q,fr(f,p),cs,a,g,b)
def vocabulary(s,gs,vs,av,q,cs,a,g,b):return choose(s,'vocabulary',gs,vs,av,q,ru('Выберите реплику по всем условиям.'),[fr(f,p) for f,p in cs],a,g,b)
def warmup(s,unit,lesson,task):
 prior=json.loads((OUT/f'{unit}.v1.json').read_text());t=copy.deepcopy(next(t for t in prior['sessions'][lesson-1]['tasks'] if t['id']==task));t['id']=f'Q{len(s["tasks"])+1:02}';s['tasks'].append(t)
 for o in t['objective_ids']:
  if o not in {x['id'] for x in s['objectives']}:s['objectives'].append(copy.deepcopy(OBJECTIVES[o]))

s=start(1,'Различите прежний опыт изучения французского, отсутствие такого опыта и желание учиться.',[])
warmup(s,'A2-U12',2,'Q05')
intro(s,2,'Déjà в модели J’ai déjà appris le français означает, что человек раньше уже учил французский. Je n’ai jamais appris le français отрицает такой опыт: «Я никогда не учил французский». Здесь jamais находится в полной отрицательной рамке. Эти слова показаны в контексте опыта, не как список всех возможных значений.',['deja-experience','jamais-experience'],[('Déjà','дэжа́'),('J’ai déjà appris le français','жэ дэжа апри лё фра(н)сэ́'),('Je n’ai jamais appris le français','жё нэ жамэ апри лё фра(н)сэ́'),('jamais','жамэ́')])
intro(s,2,'Appris — выбранная форма знакомого apprendre для passé composé. В показанных моделях déjà / jamais стоят между вспомогательной формой и appris. Прежний опыт не доказывает полного владения языком. Je voudrais apprendre le français сообщает о желании, а не само по себе о прошлом опыте.',['apprendre','avoir-pc','je-voudrais'],[('Appris','апри́'),('apprendre','апра́(н)др'),('passé composé','пасэ ко(н)позэ́'),('déjà','дэжа́'),('appris','апри́'),('Je voudrais apprendre le français','жё вудрэ апра(н)др лё фра(н)сэ́')],('J’ai déjà appris le français. Je n’ai jamais appris le français. Je voudrais apprendre le français.','жэ дэжа апри лё фра(н)сэ́. жё нэ жамэ апри лё фра(н)сэ́. жё вудрэ апра(н)др лё фра(н)сэ́.'))
